        currentDir = None
    if isinstance(currentDir, DirHandle):
        kwargs['currentDir'] = currentDir.name()
    now = str(time.strftime('%Y.%m.%d %H:%M:%S'))
    name = 'LogEntry_' + now + '_' + str(int(time.time()))
    entry = {'docs': None, 'reasons': None, 'message': msg, 'timestamp': now, 'importance': importance, 'msgType': msgType, 'exception': exception}
    for k in kwargs:
        entry[k] = kwargs[k]
    self.processEntry(entry)
    self.saveEntry({name: entry})
    self.displayEntry(entry)

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    table_wc = repo.working_copy.tabular
    result = []
    if table_wc:
        for part in table_wc.parts:
            part_status = {'path': part.clean_location, 'changes': get_diff_status_json(part)}
            result.append(part_status)
    return result

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    table_wc = repo.working_copy.tabular
    table_wc_paths = [part.clean_location for part in table_wc] if table_wc else []
    result = {'paths': table_wc_paths, 'changes': get_diff_status_json(repo)}
    return result

def connect(self):
    log.info('Attempting to connect to news server...')
    ssl = config.news.pop('ssl', False)
    compression = config.news.pop('compression', False)
    try:
        if ssl:
            self.connection = nntplib.NNTP_SSL(**config.news)
        else:
            self.connection = nntplib.NNTP(**config.news)
        if compression:
            log.info('Compression is enabled, but no library support is available.')
    except Exception as e:
        log.error('Could not connect to news server: ' + str(e))
        return False
    log.info('Connected!')
    return True

def compute_hint_frame_locations(self, operations):
    op = operations[-1]
    if op.getopnum() != rop.JUMP:
        return
    self.final_jump_op = op
    descr = op.getdescr()
    assert isinstance(descr, TargetToken)
    if descr._ll_loop_code != 0:
        self._compute_hint_frame_locations_from_descr(descr)

def run_ingest_job_and_kick_scheduler_on_completion(self, args: IngestArgsType):
    self._run_ingest_job(args)
    while not self.is_ingest_job_complete():
        time.sleep(0.1)
    self.kick_scheduler()
    logging.info('Done running task. Returning from run_ingest_job_and_kick_scheduler_on_completion')

import sys
from PyQt5.QtWidgets import QFileDialog

def on_pbSphinxExecutable_clicked(self):
    if sys.platform.startswith('win'):
        filter_str = 'sphinx-build.exe;; All Files (*.*)'
    else:
        filter_str = 'sphinx-build.py;; All Files (*.*)'
    path = QFileDialog.getOpenFileName(self, 'Select Sphinx executable', '', filter=filter_str)
    if path:
        self.leSphinxExecutable.setText(path[0])

class Decoder:

    def __init__(self):
        self.wren_seen = False

    def handle_wren(self, mosi, miso):
        self.putx([Ann.WREN, self.cmd_ann_list()])
        self.wren_seen = True
        self.state = None

    def handle_ce2(self, mosi, miso):
        if not self.wren_seen:
            print('Warning: WREN was not seen before.')
        self.putx([Ann.CE2, self.cmd_ann_list()])

def handle_ce2(self, mosi, miso):
    if not hasattr(self, 'wren_seen') or not self.wren_seen:
        print('Warning: WREN was not seen before.')
