def finish_song_deletion(self, coresong):

    def update_cb(conn, res):
        if res is None or not res.success:
            self._log.error('Failed to update the database after song deletion.')
        else:
            conn.update_finish(res)
        self._notificationmanager.pop_loading()

    def entry_retrieved_cb(source, op_id, media, remaining, error):
        if error:
            self._log.warning('Error: {}'.format(error))
            return
        if not media:
            return
        self._notificationmanager.push_loading()
        update_query = '
        INSERT OR REPLACE {
            ?entry nfo:listPosition ?position .
        }
        WHERE {
            SELECT ?entry
                   (?old_position - 1) AS ?position
            WHERE {
                ?entry a nfo:MediaFileListEntry ;
                         nfo:listPosition ?old_position .
                ?playlist nfo:hasMediaFileListEntry ?entry .
                FILTER (?old_position > ?removed_position)
                {
                    SELECT ?playlist
                           ?removed_position
                    WHERE {
                        ?playlist a nmm:Playlist ;
                                  a nfo:MediaList ;
                                    nfo:hasMediaFileListEntry
                                    ?removed_entry .
                        ?removed_entry nfo:listPosition ?removed_position .
                        FILTER (
                            tracker:id(?playlist) = %(playlist_id)s &&
                            tracker:id(?removed_entry) = %(entry_id)s
                        )
                    }
                }
            }
        };
        INSERT OR REPLACE {
            ?playlist nfo:entryCounter ?new_counter .
        }
        WHERE {
            SELECT ?playlist
                   (?counter - 1) AS ?new_counter
            WHERE {
                ?playlist a nmm:Playlist ;
                          a nfo:MediaList ;
                            nfo:entryCounter ?counter .
                FILTER (
                    tracker:id(?playlist) = %(playlist_id)s
                )
            }
        };
        DELETE {
            ?playlist nfo:hasMediaFileListEntry ?entry .
            ?entry a rdfs:Resource .
        }
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            FILTER (
                tracker:id(?playlist) = %(playlist_id)s &&
                tracker:id(?entry) = %(entry_id)s
            )
        }
        '.replace('
', ' ').strip() % {'playlist_id': self.props.pl_id, 'entry_id': media.get_id()}
        self._tracker.update_async(update_query, None, update_cb)
    song_id = coresong.props.media.get_id()
    entry_query = '
    SELECT
        %(media_type)s AS ?type
        ?entry AS ?id
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            ?entry a nfo:MediaFileListEntry ;
                     nfo:entryUrl ?url .
            SERVICE <dbus:%(miner_fs_busname)s> {
                GRAPH tracker:Audio {
                    SELECT
                        ?song
                        ?url
                    WHERE {
                        ?song a nmm:MusicPiece ;
                              nie:isStoredAs ?url .
                        FILTER (
                            %(filter_clause_song)s
                        )
                    }
                }
            }
            FILTER (
                %(filter_clause_pl)s
            )
        }
    '.replace('
', ' ').strip() % {'media_type': int(Grl.MediaType.AUDIO), 'filter_clause_song': 'tracker:id(?song) = ' + song_id, 'filter_clause_pl': 'tracker:id(?playlist) = ' + self.props.pl_id, 'miner_fs_busname': self._tracker_wrapper.props.miner_fs_busname}
    self._source.query(entry_query, [Grl.METADATA_KEY_ID], self._fast_options, entry_retrieved_cb)

import arrow

def chunk_date_range(self, start_date: Union[int, str, datetime], end_date: Union[int, str, datetime], chunk_size: int, chunk_unit: Optional[str]='months', date_format: Optional[str]=None) -> Tuple[Union[datetime, str], Union[datetime, str]]:
    relative_delta_settings = {chunk_unit: +chunk_size}
    if isinstance(start_date, (int, str)):
        start_date = self.any_to_datetime(start_date)
    if isinstance(end_date, (int, str)):
        end_date = self.any_to_datetime(end_date)
    sd = start_date
    ed = min(end_date, start_date + relativedelta(**relative_delta_settings))
    while 1:
        sdf = sd
        edf = ed
        if date_format is not None:
            sdf = arrow.get(sd).format(date_format)
            edf = arrow.get(ed).format(date_format)
        yield (sdf, edf)
        if ed >= end_date:
            break
        sd = ed
        ed = min(end_date, sd + relativedelta(**relative_delta_settings))

def RenewSliver(self, slice_urn, credentials, expiration_time):
    self.logger.info('RenewSliver(%r, %r)' % (slice_urn, expiration_time))
    privileges = (RENEWSLIVERPRIV,)
    creds = self._cred_verifier.verify_from_strings(self._server.pem_cert, credentials, slice_urn, privileges)
    if slice_urn in self._slivers:
        sliver = self._slivers.get(slice_urn)
        requested = dateutil.parser.parse(str(expiration_time))
        for cred in creds:
            if cred.expiration < requested:
                self.logger.debug('Cant renew sliver %r until %r cause one of %d credential(s) (%r) expires before then', slice_urn, expiration_time, len(creds), cred.get_gid_object().get_hrn())
                return False
        sliver.expiration = requested
        self.logger.info('Sliver %r now expires on %r', slice_urn, expiration_time)
        return True
    else:
        self.no_such_slice(slice_urn)

