def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    elif blocksize is not None:
        from scipy.sparse import bsr_matrix
        coo = self.tocoo(copy=False)
        return bsr_matrix((coo.data, (coo.row, coo.col)), shape=coo.shape, blocksize=blocksize, copy=copy)
    else:
        return self.tocoo(copy=False).tobsr(blocksize=blocksize)

def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        coo = self.tocoo(copy=False)
        return coo.tobsr(blocksize=blocksize, copy=copy)

