def run_cmd(self, command_list, allow_fail=False, error_msg=None, cwd=None):
    if isinstance(command_list, str):
        command_list = shlex.split(command_list)
    elif not isinstance(command_list, list):
        raise LAVABug('commands to run_cmd need to be a list or a string')
    command_list = ['nice'] + [str(s) for s in command_list]
    self.logger.debug("Calling: '%s'", "' ".join(command_list))
    start = time.time()
    proc = subprocess.Popen(command_list, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1, universal_newlines=True, encoding='utf-8', errors='replace')
    poller = select.epoll()
    poller.register(proc.stdout, select.EPOLLIN)
    poller.register(proc.stderr, select.EPOLLIN)
    while proc.poll() is None:
        for (fd, event) in poller.poll():
            if event is not select.EPOLLIN:
                continue
            if fd == proc.stdout.fileno():
                line = proc.stdout.readline()
                self.logger.debug('>> %s', line)
            elif fd == proc.stderr.fileno():
                line = proc.stderr.readline()
                self.logger.error('>> %s', line)
    for line in proc.stdout.readlines():
        self.logger.debug('>> %s', line)
    for line in proc.stderr.readlines():
        self.logger.error('>> %s', line)
    ret = proc.wait()
    self.logger.debug('Returned %d in %s seconds', ret, int(time.time() - start))
    if ret and (not allow_fail):
        self.logger.error("Unable to run '%s'", command_list)
        raise self.command_exception(error_msg)

def solve_output(self, **input_types):
    solved_outputs = self.outputs
    for (output_name, spec) in solved_outputs.items():
        if not spec.qiime_type.is_concrete():
            raise TypeError('Solved output %r must be a concrete type, not %r' % (output_name, spec.qiime_type))
    return solved_outputs

def solve_output(self, **input_types):
    solved_outputs = self.outputs
    for (output_name, spec) in solved_outputs.items():
        if not spec.qiime_type.is_concrete():
            if not self.can_solve_output(output_name, input_types):
                raise TypeError('Solved output %r must be a concrete type, not %r' % (output_name, spec.qiime_type))
    return solved_outputs

def can_solve_output(self, output_name, input_types):
    return all((input_type in self.inputs for input_type in input_types))

from xml.sax.saxutils import escape

def setAuthors(template, authors):
    text = ''
    for (name, href) in authors:
        escaped_name = escape(name)
        escaped_href = escape(href)
        anchor = '<a href="%s">%s</a>' % (escaped_href, escaped_name)
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','
    childNodes = microdom.parseString('<span>' + text + '</span>').childNodes
    for node in domhelpers.findElementsWithAttribute(template, 'class', 'authors'):
        node.childNodes.extend(childNodes)
    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString('<link rel="author" href="%s" title="%s"/>' % (escaped_href, escaped_name)).childNodes[0] for (name, href) in authors]
    head.childNodes.extend(authors)

def dotedges(expr, atom=lambda x: not isinstance(x, Basic), pos=(), repeat=True):
    if atom(expr):
        return []
    else:
        expr_str = purestr(expr)
        arg_strs = [purestr(arg) for arg in expr.args]
        if repeat:
            expr_str += '_%s' % str(pos)
            arg_strs = [arg_str + '_%s' % str(pos + (i,)) for (i, arg_str) in enumerate(arg_strs)]
        return ['"%s" -> "%s";' % (expr_str, arg_str) for arg_str in arg_strs]

def dotedges(expr, atom=lambda x: not isinstance(x, Basic), pos=(), repeat=True):
    if atom(expr):
        return []
    else:
        expr_str = purestr(expr)
        arg_strs = [expr_str + '_%s' % str(pos + (i,)) for i in range(len(expr.args))]
        if repeat:
            expr_str += '_%s' % str(pos)
        return ['"%s" -> "%s";' % (expr_str, arg_str) for arg_str in arg_strs]

def on_window_keypress_event(self, widget, event, user_data=None):
    if check_keypress(event, ['Control', 'f']):
        self.search_box.grab_focus()
        return True
    if check_keypress(event, ['Control', 's']):
        self.save_launcher()
        return True
    return False

from typing import Optional

def lookup_class(kind: str, apiVersion: Optional[str]=None, default: Optional[str]=None) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className)
    except ImportError:
        klass = None
    if klass:
        register_class(className, klass)
    return klass

import pandas as pd

class Christmas:

    @staticmethod
    def observance(date):
        return date

class USNewYearsDay:

    @staticmethod
    def observance(date):
        return date

class GoodFriday:

    @staticmethod
    def _apply_rule(dt):
        return dt

def good_friday_unless_christmas_nye_friday(dts):
    years = dts.dt.year
    christmas_weekdays = Christmas.observance(pd.Timestamp(years, 12, 25)).weekday()
    nyd_weekdays = USNewYearsDay.observance(pd.Timestamp(years, 1, 1)).weekday()
    valid_days = (christmas_weekdays != 4) & (nyd_weekdays != 4)
    return GoodFriday._apply_rule(dts[valid_days]) if valid_days.any() else pd.NaT

import pandas as pd

def good_friday_unless_christmas_nye_friday(dt):
    if not isinstance(dt, pd.Series):
        dt = pd.Series([dt])
    year = dt.dt.year
    christmas_weekday = pd.Timestamp(year.astype(str) + '-12-25').weekday()
    nyd_weekday = pd.Timestamp(year.astype(str) + '-01-01').weekday()
    valid_days = (christmas_weekday != 4) & (nyd_weekday != 4)
    good_friday_days = GoodFriday._apply_rule(dt)
    return pd.Series(good_friday_days.where(valid_days, pd.NaT), index=dt.index)

def __init__(self, options=None, register_classes=()):
    self.logger.debug('Creating %s arch', self.name)
    self.option_settings = {o: False for o in self.option_names}
    if options:
        assert isinstance(options, tuple)
        for option_name in options:
            assert option_name in self.option_names
            self.option_settings[option_name] = True
    self.register_classes = register_classes
    self.byte_sizes = {}
    self.byte_sizes['int'] = 4
    self.byte_sizes['ptr'] = 4
    self.byte_sizes['byte'] = 1
    self.byte_sizes['u8'] = 1
    self.FrameClass = Frame

def execute(self, context):
    obj_list = context.selected_objects
    if not obj_list:
        self.report({'ERROR'}, 'No objects selected')
        return {'CANCELLED'}
    mat_list = util.materialsFromObj(obj_list)
    if not mat_list:
        self.report({'ERROR'}, 'No materials found on selected objects')
        return {'CANCELLED'}
    engine = context.scene.render.engine
    count = 0
    for mat in mat_list:
        passes = generate.get_textures(mat)
        if not self.useExtraMaps:
            for pass_name in passes:
                if pass_name != 'diffuse':
                    passes[pass_name] = None
            if self.autoFindMissingTextures:
                for pass_name in passes:
                    res = generate.replace_missing_texture(passes[pass_name])
                    if res > 0:
                        mat['texture_swapped'] = True
            if mat.library:
                res = generate.matprep_linked(mat, passes, self.useReflections, self.makeSolid)
            elif engine == 'BLENDER_RENDER' or engine == 'BLENDER_GAME':
                res = generate.matprep_internal(mat, passes, self.useReflections, self.makeSolid)
                if res == 0:
                    count += 1
                if self.animateTextures:
                    sequences.animate_single_material(mat, context.scene.render.engine)
            elif engine == 'CYCLES' or engine == 'BLENDER_EEVEE':
                res = generate.matprep_cycles(mat, passes, self.useReflections, self.usePrincipledShader, self.makeSolid)
                if res == 0:
                    count += 1
                if self.animateTextures:
                    sequences.animate_single_material(mat, context.scene.render.engine)
            else:
                self.report({'ERROR'}, 'Only blender internal or cycles supported')
                return {'CANCELLED'}
    if self.combineMaterials is True:
        bpy.ops.mcprep.combine_materials(selection_only=True, skipUsage=True)
    if self.improveUiSettings:
        bpy.ops.mcprep.improve_ui()
    self.report({'INFO'}, 'Modified ' + str(count) + ' materials')
    self.track_param = context.scene.render.engine
    self.track_exporter = generate.detect_form(mat_list)
    return {'FINISHED'}

def execute(self, context):
    obj_list = context.selected_objects
    if not obj_list:
        self.report({'ERROR'}, 'No objects selected')
        return {'CANCELLED'}
    mat_list = util.materialsFromObj(obj_list)
    if not mat_list:
        self.report({'ERROR'}, 'No materials found on selected objects')
        return {'CANCELLED'}
    engine = context.scene.render.engine
    count = 0
    for mat in mat_list:
        passes = generate.get_textures(mat)
        if not self.useExtraMaps:
            for pass_name in passes:
                if pass_name != 'diffuse':
                    passes[pass_name] = None
            if self.autoFindMissingTextures:
                for pass_name in passes:
                    res = generate.replace_missing_texture(passes[pass_name])
                    if res > 0:
                        mat['texture_swapped'] = True
            if mat.get('is_linked', False):
                self.report({'WARNING'}, 'Linked material detected, skipping processing for: {}'.format(mat.name))
                continue
        if engine == 'BLENDER_RENDER' or engine == 'BLENDER_GAME':
            res = generate.matprep_internal(mat, passes, self.useReflections, self.makeSolid)
            if res == 0:
                count += 1
            if self.animateTextures:
                sequences.animate_single_material(mat, context.scene.render.engine)
        elif engine == 'CYCLES' or engine == 'BLENDER_EEVEE':
            res = generate.matprep_cycles(mat, passes, self.useReflections, self.usePrincipledShader, self.makeSolid)
            if res == 0:
                count += 1
            if self.animateTextures:
                sequences.animate_single_material(mat, context.scene.render.engine)
        else:
            self.report({'ERROR'}, 'Only blender internal or cycles supported')
            return {'CANCELLED'}
    if self.combineMaterials is True:
        bpy.ops.mcprep.combine_materials(selection_only=True, skipUsage=True)
    if self.improveUiSettings:
        bpy.ops.mcprep.improve_ui()
    self.report({'INFO'}, 'Modified ' + str(count) + ' materials')
    self.track_param = context.scene.render.engine
    self.track_exporter = generate.detect_form(mat_list)
    return {'FINISHED'}

def unregisterConsumer(self, consumerId: str) -> bool:
    method = '/consumers/%s' % self.sanitize(consumerId)
    response = self.conn.request_delete(method, description=_('Unregistering system'))
    if response.status_code == 204:
        return True
    return False

def unregisterConsumer(self, consumerId: str) -> None:
    method = '/consumers/%s' % self.sanitize(consumerId)
    response = self.conn.request_delete(method, description=_('Unregistering system'))
    if response.status == 204:
        return True
    return None

import logging
logging.basicConfig(level=logging.INFO)

def get_metric(name):
    try:
        return METRIC_REGISTRY[name]
    except KeyError:
        logging.warning(f"Could not find registered metric '{name}' in lm-eval, searching in HF Evaluate library...")
        try:
            metric_object = evaluate.load(name)
            return metric_object.compute
        except Exception:
            eval_logger.error('{} not found in the evaluate library!'.format(name), 'Please check https://huggingface.co/evaluate-metric')

def add_image(self, can_remove=True):

    class ImageSettings(cps.SettingGroup):

        def __init__(self, images):
            super().__init__()
            self.key = uuid.uuid4()
            self.image_name = cps.ImageNameSubscriber('Select the input image', 'None')
            self.add_setting(self.image_name)
            if can_remove:

                def remove(images=images, key=self.key):
                    index = [x.key for x in images].index(key)
                    del images[index]
                self.remove_button = cps.DoSomething('Remove above image', 'Remove', remove)
                self.add_setting(self.remove_button)
    self.images.append(ImageSettings(self.images))

def add_image(self, can_remove=True):

    class ImageSettings(cps.SettingGroup):

        def __init__(self, images):
            super().__init__()
            self.key = uuid.uuid4()
            self.image_name = cps.ImageNameSubscriber('Select the input image', 'None')
            if can_remove:

                def remove(images=images, key=self.key):
                    index = [x.key for x in images].index(key)
                    del images[index]
                self.remove_button = cps.DoSomething('Remove above image', 'Remove', remove)
            self.add_setting(self.image_name)
            if can_remove:
                self.add_setting(self.remove_button)

        def settings(self):
            return [self.image_name]
    self.images.append(ImageSettings(self.images))

def get_package_members(package: db_models.Package=Depends(get_package_or_fail), dao: Dao=Depends(get_dao)):
    member_list = dao.get_package_members(package.channel.name, package.name)

    def transform_member(member):
        return {'id': str(uuid.UUID(bytes=member.user.id)), 'profile': member.user.profile}
    transformed_members = [transform_member(member) for member in member_list]
    return transformed_members

def set_doc_variables(item, job, params):
    change = item.change
    doc_subpath = ''
    if hasattr(change, 'ref'):
        tag = re.match('^refs/tags/(.*)', change.ref)
        if tag:
            doc_subpath = tag.group(1)
        else:
            doc_subpath = change.ref
    elif hasattr(change, 'refspec'):
        doc_subpath = change.branch
    if doc_subpath:
        params['DOC_SUBPATH'] = doc_subpath
    if 'ZUUL_PROJECT' in params:
        raw_project = params['ZUUL_PROJECT']
        if raw_project in doc_destination:
            raw_project = doc_destination[raw_project]
        elif raw_project.startswith('mediawiki/extensions/'):
            raw_project = raw_project.split('/')[-1]
        params['DOC_PROJECT'] = raw_project.replace('/', '-')
        params['DOC_BASENAME'] = params['ZUUL_PROJECT'].split('/')[-1]

def getWeaponSystemData(fit, spoolupValue=1):
    weaponSystems = []
    groups = {}
    spoolOptions = SpoolOptions(SpoolType.SCALE, spoolupValue, False)
    for mod in fit.modules:
        if mod.getDps(spoolOptions=spoolOptions).total > 0:
            keystr = str(mod.itemID) + '-' + str(mod.chargeID)
            if keystr in groups:
                groups[keystr][1] += 1
            else:
                groups[keystr] = [mod, 1]
    for wepGroup in groups.values():
        stats = wepGroup[0]
        n = wepGroup[1]
        tracking = 0
        maxVelocity = 0
        explosionDelay = 0
        damageReductionFactor = 0
        explosionRadius = 0
        explosionVelocity = 0
        aoeFieldRange = 0
        typeing = 'None'
        if stats.charge:
            name = stats.item.name + ', ' + stats.charge.name
        else:
            name = stats.item.name
        if stats.hardpoint == Hardpoint.TURRET:
            tracking = stats.getModifiedItemAttr('trackingSpeed')
            typeing = 'Turret'
        elif stats.hardpoint == Hardpoint.MISSILE or 'Bomb Launcher' in stats.item.name:
            maxVelocity = stats.getModifiedChargeAttr('maxVelocity')
            explosionDelay = stats.getModifiedChargeAttr('explosionDelay')
            damageReductionFactor = stats.getModifiedChargeAttr('aoeDamageReductionFactor')
            explosionRadius = stats.getModifiedChargeAttr('aoeCloudSize')
            explosionVelocity = stats.getModifiedChargeAttr('aoeVelocity')
            typeing = 'Missile'
        elif stats.hardpoint == Hardpoint.NONE:
            aoeFieldRange = stats.getModifiedItemAttr('empFieldRange')
            typeing = 'SmartBomb'
        if stats.item.group.name == 'Super Weapon' and stats.maxRange is None:
            maxRange = 300000
        else:
            maxRange = stats.maxRange
        statDict = {'dps': stats.getDps(spoolOptions=spoolOptions).total * n, 'capUse': stats.capUse * n, 'falloff': stats.falloff, 'type': typeing, 'name': name, 'optimal': maxRange, 'numCharges': stats.numCharges, 'numShots': stats.numShots, 'reloadTime': stats.reloadTime, 'cycleTime': stats.cycleTime, 'volley': stats.getVolley(spoolOptions=spoolOptions).total * n, 'tracking': tracking, 'maxVelocity': maxVelocity, 'explosionDelay': explosionDelay, 'damageReductionFactor': damageReductionFactor, 'explosionRadius': explosionRadius, 'explosionVelocity': explosionVelocity, 'aoeFieldRange': aoeFieldRange, 'damageMultiplierBonusMax': stats.getModifiedItemAttr('damageMultiplierBonusMax'), 'damageMultiplierBonusPerCycle': stats.getModifiedItemAttr('damageMultiplierBonusPerCycle')}
        weaponSystems.append(statDict)
    for drone in fit.drones:
        if drone.getDps().total > 0 and drone.amountActive > 0:
            droneAttr = drone.getModifiedItemAttr
            newTracking = droneAttr('trackingSpeed') / (droneAttr('optimalSigRadius') / 40000)
            statDict = {'dps': drone.getDps().total, 'cycleTime': drone.cycleTime, 'type': 'Drone', 'optimal': drone.maxRange, 'name': drone.item.name, 'falloff': drone.falloff, 'maxSpeed': droneAttr('maxVelocity'), 'tracking': newTracking, 'volley': drone.getVolley().total}
            weaponSystems.append(statDict)
    for fighter in fit.fighters:
        if fighter.getDps().total > 0 and fighter.amountActive > 0:
            fighterAttr = fighter.getModifiedItemAttr
            abilities = []
            if 'fighterAbilityAttackMissileDamageEM' in fighter.item.attributes.keys():
                baseRef = 'fighterAbilityAttackMissile'
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            if 'fighterAbilityMissilesDamageEM' in fighter.item.attributes.keys():
                baseRef = 'fighterAbilityMissiles'
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            statDict = {'dps': fighter.getDps().total, 'type': 'Fighter', 'name': fighter.item.name, 'maxSpeed': fighterAttr('maxVelocity'), 'abilities': abilities, 'ehp': fighterAttr('shieldCapacity') / 0.8875 * fighter.amountActive, 'volley': fighter.getVolley().total, 'signatureRadius': fighterAttr('signatureRadius')}
            weaponSystems.append(statDict)
    return weaponSystems

