def __init__(self, dataDir):
    super(FileSystemBackend, self).__init__()
    self._dataDir = dataDir
    self.load_reference_sets()
    self.load_datasets()

def load_reference_sets(self):
    referencesDirName = 'references'
    referenceSetDir = os.path.join(self._dataDir, referencesDirName)
    for referenceSetName in os.listdir(referenceSetDir):
        relativePath = os.path.join(referenceSetDir, referenceSetName)
        if os.path.isdir(relativePath):
            referenceSet = references.HtslibReferenceSet(referenceSetName, relativePath, self)
            self.addReferenceSet(referenceSet)

def load_datasets(self):
    datasetDirs = [os.path.join(self._dataDir, directory) for directory in os.listdir(self._dataDir) if os.path.isdir(os.path.join(self._dataDir, directory)) and directory != 'references']
    for datasetDir in datasetDirs:
        dataset = datasets.FileSystemDataset(datasetDir, self)
        self.addDataset(dataset)

def render(self, just_html=False):
    if not just_html:
        if self.is_internet_explorer():
            self.headers['Content-Type'] = 'text/html'
            self.xml = None
    return basepage.render(self, just_html)

def is_internet_explorer(self):
    return 'MSIE' in self.user_agent or 'Trident' in self.user_agent

def _update_job(self, job_id, state=None, **kwargs):
    with self.session_scope() as session:
        try:
            (job, orm_job) = self._get_job_and_orm_job(job_id, session)
            if state is not None:
                orm_job.state = state
            for (kwarg, value) in kwargs.items():
                setattr(orm_job.obj, kwarg, value)
            session.add(orm_job)
            return (orm_job.obj, orm_job)
        except JobNotFound:
            if state:
                logger.error('Tried to update job with id {} with state {} but it was not found'.format(job_id, state))
            else:
                logger.error('Tried to update job with id {} but it was not found'.format(job_id))

