def test_run_qobj(self):
    try:
        simulator = qiskitsimulator.QISKitCppSimulator()
    except FileNotFoundError as fnferr:
        raise unittest.SkipTest('cannot find {} in path'.format(fnferr))
    result = simulator.run(self.q_job)
    expected2 = {'000 000': 18, '001 001': 15, '010 010': 13, '011 011': 11, '100 100': 10, '101 101': 10, '110 110': 12, '111 111': 11}
    actual_counts = result.get_counts('test_circuit2')
    for (key, expected_count) in expected2.items():
        actual_count = actual_counts.get(key, 0)
        self.assertAlmostEqual(actual_count, expected_count, delta=2, msg=f'Count for {key} is not within acceptable range.')

def process_dependencies(self, task, deplist, uowcommit, delete=False):
    if delete:
        if self.cascade.delete_orphan or self.post_update:
            for obj in deplist:
                childlist = self.get_object_dependencies(obj, uowcommit, passive=self.passive_deletes)
                if childlist is not None:
                    for child in childlist.deleted_items():
                        if child is not None and childlist.hasparent(child) is False:
                            self._synchronize(obj, child, None, True, uowcommit)
                            self._conditional_post_update(child, uowcommit, [obj])
                    for child in childlist.unchanged_items():
                        if child is not None:
                            self._synchronize(obj, child, None, True, uowcommit)
                            self._conditional_post_update(child, uowcommit, [obj])
    else:
        for obj in deplist:
            childlist = self.get_object_dependencies(obj, uowcommit, passive=True)
            if childlist is not None:
                for child in childlist.added_items():
                    self._synchronize(obj, child, None, False, uowcommit)
                    self._conditional_post_update(child, uowcommit, [obj])
                for child in childlist.deleted_items():
                    if not self.cascade.delete_orphan and (not self._get_instrumented_attribute().hasparent(child)):
                        self._synchronize(obj, child, None, True, uowcommit)

def dict_for_mongo(_dict):
    for (key, value) in _dict.items():
        if _is_invalid_for_mongo(key):
            del _dict[key]
            key = _encode_for_mongo(key)
        if isinstance(value, list):
            _dict[key] = [dict_for_mongo(obj) if isinstance(obj, dict) else obj for obj in value]
        elif isinstance(value, dict):
            _dict[key] = dict_for_mongo(value)
        else:
            _dict[key] = _convert_to_string(value)
    return _dict

def _convert_to_string(value):
    if isinstance(value, datetime64):
        return str(value)
    elif isinstance(value, (int, float, bool)):
        return str(value)
    return value

def append_changelog_changes_collections(builder: RstBuilder, changelog_entry: ChangelogEntry, is_last: bool) -> PluginDataT:
    result: PluginDataT = []
    if changelog_entry.changed_collections:
        if is_last:
            builder.add_section('Included Collections', 1)
        else:
            builder.add_section('Changed Collections', 1)
        for (collector, collection_version, prev_collection_version) in changelog_entry.changed_collections:
            if is_last:
                msg = f'{collector.collection} with version {collection_version}.'
                if prev_collection_version is not None:
                    msg += f' This was upgraded from version {prev_collection_version}.'
            elif prev_collection_version is None:
                msg = f'{collector.collection} was upgraded to version {collection_version}.'
            else:
                msg = f'{collector.collection} was upgraded from'
                msg += f' version {prev_collection_version} to version {collection_version}.'
            msg += '\n'
            changelog = collector.changelog
            if changelog:
                release_entries = changelog.generator.collect(squash=True, after_version=prev_collection_version, until_version=collection_version)
                if not release_entries:
                    msg += 'The collection did not have a changelog in this version.'
                elif release_entries[0].empty:
                    msg += 'There are no changes recorded in the changelog.'
                else:
                    result.append((collector.collection, f'{collector.collection}.', changelog.generator, release_entries[0]))
                    msg += 'The changes are reported in the combined changelog below.'
            else:
                msg += 'Unfortunately, this collection does not provide changelog data in a format '
                msg += 'that can be processed by the changelog generator.'
                msg += f" Please refer to the collection's changelog here: {collector.changelog_url}"
            builder.add_list_item(msg)
        builder.add_raw_rst('')
    return result

def from_dist(cls, dist, dependency_links, find_tags=False):
    location = os.path.normcase(os.path.abspath(dist.location))
    comments = []
    from pip.vcs import vcs, get_src_requirement
    if vcs.get_backend_name(location):
        editable = True
        try:
            req = get_src_requirement(dist, location, find_tags)
        except InstallationError as exc:
            logger.warn('Error when trying to get requirement for VCS system %s, falling back to uneditable format' % exc)
            req = None
        if req is None:
            logger.warn('Could not determine repository location of %s' % location)
            comments.append('## !! Could not determine repository location')
            req = dist.as_requirement()
            editable = False
    else:
        editable = False
        req = dist.as_requirement()
        specs = req.specs
        assert len(specs) == 1 and specs[0][0] == '=='
        version = specs[0][1]
        ver_match = cls._rev_re.search(version)
        date_match = cls._date_re.search(version)
        if ver_match or date_match:
            svn_backend = vcs.get_backend('svn')
            if svn_backend:
                svn_location = svn_backend().get_location(dist, dependency_links)
            if not svn_location:
                logger.warn('Warning: cannot find svn location for %s' % req)
                comments.append('## NOTE: SVN URL not found in dependency_links. Consider checking the provided links or the package configuration.')
            else:
                comments.append('# Installing as editable to satisfy requirement %s:' % req)
                if ver_match:
                    rev = ver_match.group(1)
                else:
                    rev = '{%s}' % date_match.group(1)
                editable = True
                req = '%s@%s#egg=%s' % (svn_location, rev, cls.egg_name(dist))
    return cls(dist.project_name, req, editable, comments)

def mbox_uuid(self):
    if self.mbox_wrapper is None:
        raise ValueError('mbox_wrapper is None')
    return self.mbox_wrapper.uuid

def method(self, methodId, objId, className, methodName, args=None, packageName='qpid'):
    codec = Codec(StringIO(), self.spec)
    codec.encode_long(methodId)
    codec.encode_longlong(objId)
    codec.encode_shortstr(self.rqname)
    if args is not None:
        for (key, value) in args.items():
            if isinstance(value, int):
                codec.encode_long(value)
            elif isinstance(value, str):
                codec.encode_shortstr(value)
            elif isinstance(value, bytes):
                codec.encode_longstr(value)
    if methodName == 'echo':
        codec.encode_long(args['sequence'])
        codec.encode_longstr(args['body'])
    msg = Content(codec.stream.getvalue())
    msg['content_type'] = 'application/octet-stream'
    msg['routing_key'] = 'method.' + packageName + '.' + className + '.' + methodName
    msg['reply_to'] = self.spec.struct('reply_to')
    self.channel.message_transfer(destination='qpid.management', content=msg)

def method(self, methodId, objId, className, methodName, args=None, packageName='qpid'):
    codec = Codec(StringIO(), self.spec)
    codec.encode_long(methodId)
    codec.encode_longlong(objId)
    codec.encode_shortstr(self.rqname)
    if args is not None:
        for (key, value) in args.items():
            if key == 'sequence':
                codec.encode_long(value)
            elif key == 'body':
                codec.encode_longstr(value)
    msg = Content(codec.stream.getvalue())
    msg['content_type'] = 'application/octet-stream'
    msg['routing_key'] = 'method.' + packageName + '.' + className + '.' + methodName
    msg['reply_to'] = self.spec.struct('reply_to')
    self.channel.message_transfer(destination='qpid.management', content=msg)

def _validate_requested_port_ids(self, context, instance, neutron, requested_networks):
    ports = {}
    ordered_networks = []
    if requested_networks and (not requested_networks.auto_allocate):
        for request in requested_networks:
            if request.port_id:
                port = self._show_port(context, request.port_id, neutron_client=neutron)
                if port['tenant_id'] != instance.project_id:
                    raise exception.PortNotUsable(port_id=request.port_id, instance=instance.uuid)
                if port.get('device_id'):
                    raise exception.PortInUse(port_id=request.port_id)
                if port.get('dns_name'):
                    if port['dns_name'] != instance.hostname:
                        raise exception.PortNotUsableDNS(port_id=request.port_id, instance=instance.uuid, value=port['dns_name'], hostname=instance.hostname)
                _ensure_no_port_binding_failure(port)
                request.network_id = port['network_id']
                ports[request.port_id] = port
            if request.network_id:
                ordered_networks.append(request)
    return (ports, ordered_networks)

