def evaluate(self, eval_points, evaluate_derivatives=False):
    eval_points = numpy.asarray(eval_points)
    if numpy.any(numpy.isnan(eval_points)):
        raise ValueError('The list of points where the function is evaluated can not contain nan values.')
    results = self._compute_matrix(eval_points)
    if evaluate_derivatives:
        derivatives = self._compute_derivatives(eval_points)
        return numpy.vstack((results, derivatives))
    return results

def evaluate(self, eval_points):
    eval_points = numpy.asarray(eval_points)
    if numpy.any(numpy.isnan(eval_points)):
        raise ValueError('The list of points where the function is evaluated can not contain nan values.')
    return self._compute_matrix(eval_points)

def evaluate_derivatives(self, eval_points):
    eval_points = numpy.asarray(eval_points)
    if numpy.any(numpy.isnan(eval_points)):
        raise ValueError('The list of points where the function is evaluated can not contain nan values.')
    return self._compute_derivative_matrix(eval_points)

