def _build_samples_from_file(data_fp):
    with open(str(data_fp)) as f:
        lines = f.read().splitlines()
    samples = {}
    for line in lines:
        sample_id = line.split('\t')[0]
        read_path = str(data_fp.parent / f'{sample_id}_reads.fastq')
