def resample_and_save(predicted: Union[str, np.ndarray], target_shape: List[int], output_file: str, plans_dict_or_file: Union[dict, str], configuration_name: str, properties_dict: dict, dataset_json_dict_or_file: Union[dict, str], next_configuration: str) -> None:
    if isinstance(predicted, str):
        assert isfile(predicted), 'If isinstance(segmentation_softmax, str) then isfile(segmentation_softmax) must be True'
        del_file = deepcopy(predicted)
        predicted = np.load(predicted)
        os.remove(del_file)
    if isinstance(plans_dict_or_file, str):
        plans_dict_or_file = load_json(plans_dict_or_file)
    if isinstance(dataset_json_dict_or_file, str):
        dataset_json_dict_or_file = load_json(dataset_json_dict_or_file)
    resampling_fn = recursive_find_resampling_fn_by_name(plans_dict_or_file['configurations'][configuration_name]['resampling_fn_softmax'])
    current_spacing = plans_dict_or_file['configurations'][configuration_name]['spacing'] if len(plans_dict_or_file['configurations'][configuration_name]['spacing']) == len(properties_dict['shape_after_cropping_and_before_resampling']) else [properties_dict['spacing'][0], *plans_dict_or_file['configurations'][configuration_name]['spacing']]
    target_spacing = plans_dict_or_file['configurations'][next_configuration]['spacing'] if len(plans_dict_or_file['configurations'][next_configuration]['spacing']) == len(properties_dict['shape_after_cropping_and_before_resampling']) else [properties_dict['spacing'][0], *plans_dict_or_file['configurations'][next_configuration]['spacing']]
    predicted_array_or_file = resampling_fn(predicted, target_shape, current_spacing, target_spacing, **plans_dict_or_file['configurations'][configuration_name]['resampling_fn_softmax_kwargs'])
    segmentation = create_segmentation(predicted_array_or_file, dataset_json_dict_or_file)
    np.savez_compressed(output_file, seg=segmentation.astype(np.uint8))

def create_segmentation(predicted_array_or_file: np.ndarray, dataset_json_dict_or_file: dict) -> np.ndarray:
    use_regions = any([isinstance(i, tuple) and len(i) > 1 for i in dataset_json_dict_or_file['labels'].values()])
    if use_regions:
        regions_class_order = dataset_json_dict_or_file['regions_class_order']
        segmentation = np.zeros(predicted_array_or_file.shape[1:], dtype=np.uint8)
        for (i, c) in enumerate(regions_class_order):
            segmentation[predicted_array_or_file[i] > 0.5] = c
    else:
        segmentation = predicted_array_or_file.argmax(0)
    return segmentation

def parseTargetDirect():
    if not conf.direct:
        return
    details = None
    for dbms in SUPPORTED_DBMS:
        details = re.search("^(?P<dbms>%s)://(?P<credentials>(?P<dbmsUser>.+?)\:(?P<dbmsPass>.+?)\@)?(?P<remote>(?P<hostname>.+?)\:(?P<port>[\d]+)\/)?(?P<dbmsDb>.+?)$" % dbms, conf.direct, re.I)
        if details:
            conf.dbms     = details.group('dbms')
            if details.group('credentials'):
                conf.dbmsUser = details.group('dbmsUser')
                conf.dbmsPass = details.group('dbmsPass')
            else:
                conf.dbmsUser = str()
                conf.dbmsPass = str()
            if details.group('remote'):
                conf.hostname = details.group('hostname')
                conf.port     = int(details.group('port'))
            else:
                conf.hostname = "localhost"
                conf.port     = 0
            conf.dbmsDb   = details.group('dbmsDb')
            conf.parameters[None] = "direct connection"
            break
    if not details:
        errMsg = "invalid target details, valid syntax is for instance: 'mysql://USER:PASSWORD@DBMS_IP:DBMS_PORT/DATABASE_NAME'"
        errMsg += " and/or: 'access://DATABASE_FILEPATH'"
        raise sqlmapSyntaxException, errMsg
    dbmsDict = { "Microsoft SQL Server": [MSSQL_ALIASES, "python-pymssql", "http://pymssql.sourceforge.net/"],
                 "MySQL": [MYSQL_ALIASES, "python-mysqldb", "http://mysql-python.sourceforge.net/"],
                 "PostgreSQL": [PGSQL_ALIASES, "python-psycopg2", "http://initd.org/psycopg/"],
                 "Oracle": [ORACLE_ALIASES, "python cx_Oracle", "http://cx-oracle.sourceforge.net/"],
                 "SQLite": [SQLITE_ALIASES, "", ""],
                 "Access": [ACCESS_ALIASES, "", ""],
                 "Firebird": [FIREBIRD_ALIASES, "", ""],
                 "MongoDB": [MONGODB_ALIASES, "pymongo", "https://pymongo.readthedocs.io/en/stable/"] }
    for dbmsName, data in dbmsDict.items():
        if conf.dbms in data[0]:
            try:
                if dbmsName == "Microsoft SQL Server":
                    import pymssql
                elif dbmsName == "MySQL":
                    import MySQLdb
                elif dbmsName == "PostgreSQL":
                    import psycopg2
                elif dbmsName == "Oracle":
                    import cx_Oracle
                elif dbmsName == "MongoDB":
                    import pymongo
            except ImportError, _:
                errMsg  = "sqlmap requires %s third-party library " % data[1]
                errMsg += "in order to directly connect to the database "
                errMsg += "%s. Download from %s" % (dbmsName, data[2])
                raise sqlmapMissingDependence, errMsg

def _do_inv_for_realhost(host_config: config.HostConfig, ipaddress: Optional[HostAddress], *, parsed_sections_broker: ParsedSectionsBroker, run_only_plugin_names: Optional[Set[InventoryPluginName]]) -> InventoryTrees:
    tree_aggregator = _TreeAggregator()
    _set_cluster_property(tree_aggregator.trees.inventory, host_config)
    section.section_step('Executing inventory plugins')
    for inventory_plugin in agent_based_register.iter_all_inventory_plugins():
        if run_only_plugin_names and inventory_plugin.name not in run_only_plugin_names:
            continue
        kwargs = parsed_sections_broker.get_section_kwargs(HostKey(host_config.hostname, ipaddress, SourceType.HOST), inventory_plugin.sections)
        if not kwargs:
            console.vverbose(' %s%s%s%s: skipped (no data)\n', tty.yellow, tty.bold, inventory_plugin.name, tty.normal)
            continue
        if inventory_plugin.inventory_ruleset_name is not None:
            params = host_config.inventory_parameters(str(inventory_plugin.inventory_ruleset_name))
            if isinstance(params, dict):
                kwargs['params'] = params
            else:
                console.warning(' %s%s%s%s: invalid params type: %s', tty.red, tty.bold, inventory_plugin.name, tty.normal, type(params))
        exception = tree_aggregator.aggregate_results(inventory_plugin.inventory_function(**kwargs))
        if exception:
            console.warning(' %s%s%s%s: failed: %s', tty.red, tty.bold, inventory_plugin.name, tty.normal, exception)
        else:
            console.verbose(' %s%s%s%s', tty.green, tty.bold, inventory_plugin.name, tty.normal)
            console.vverbose(': ok\n')
    console.verbose('\n')
    tree_aggregator.trees.inventory.normalize_nodes()
    tree_aggregator.trees.status_data.normalize_nodes()
    return tree_aggregator.trees

def init_new_world(self):
    loggers_to_silence = {'world.production': None}
    for logger_name in loggers_to_silence:
        logger = logging.getLogger(logger_name)
        loggers_to_silence[logger_name] = logger.getEffectiveLevel()
        logger.setLevel(logging.WARN)
    from horizons.command.building import Build
    from horizons.command.unit import CreateUnit
    if int(self.properties.get('RandomTrees', 1)) == 1:
        tree = Entities.buildings[BUILDINGS.TREE_CLASS]
        clay = Entities.buildings[BUILDINGS.CLAY_DEPOSIT_CLASS]
        for island in self.islands:
            for tile in island.ground_map.iterkeys():
                if random.randint(0, 2) == 0 and 'constructible' in island.ground_map[tile].classes:
                    cmd = Build(self.session, tree, tile[0], tile[1], ownerless=True, island=island)
                    building = cmd.execute(self.session)
                    building.finish_production_now()
                    if random.randint(0, 40) == 0:
                        CreateUnit(island.getId(), UNITS.WILD_ANIMAL_CLASS, *tile).execute(self.session)
                elif random.randint(0, 3) == 0 and clay.build_possible(self.session, tile):
                    cmd = Build(self.session, clay, tile[0], tile[1], ownerless=True, island=island)
                    cmd.execute(self.session)
    for (logger_name, level) in loggers_to_silence.iteritems():
        logging.getLogger(logger_name).setLevel(level)
    self.trader = Trader(self.session, 99999, 'Free Trader', Color())
    ret_coords = None
    for player in self.players:
        point = self.get_random_possible_ship_position()
        ship = CreateUnit(player.getId(), UNITS.PLAYER_SHIP_CLASS, point.x, point.y).execute(self.session)
        for (res, amount) in self.session.db('SELECT resource, amount FROM start_resources'):
            ship.inventory.alter(res, amount)
        if player is self.player:
            ret_coords = (point.x, point.y)
    self.session.ingame_gui.message_widget.add(self.max_x / 2, self.max_y / 2, 'NEW_WORLD')
    assert ret_coords is not None, 'Return coords are none. No players loaded?'
    return ret_coords

def _create_cfg(self, cfg_dir, cfg_filename, cli_overrides=[]):
    is_pkg = cfg_dir.startswith('pkg://')
    if is_pkg:
        cfg_dir = cfg_dir[len('pkg://'):]
    if not is_pkg:
        if not os.path.exists(cfg_dir):
            raise IOError('conf_dir not found : {}'.format(cfg_dir))
    if cfg_filename is not None:
        main_cfg_file = os.path.join(cfg_dir, cfg_filename)
        if not ConfigLoader._exists(is_pkg, main_cfg_file):
            raise IOError('Config file not found : {}'.format(os.path.realpath(main_cfg_file)))
        main_cfg = self._load_config_impl(is_pkg, main_cfg_file)
    else:
        main_cfg = OmegaConf.create(dict(defaults=[]))
    if main_cfg.defaults is None:
        main_cfg.defaults = []
    ConfigLoader._validate_config(main_cfg)
    overrides = []
    defaults_changes = {}
    for override in cli_overrides:
        (key, value) = override.split('=')
        assert key != 'optional', 'optional is a reserved keyword and cannot be used as a config group name'
        path = os.path.join(cfg_dir, key)
        if ConfigLoader._exists(is_pkg, path):
            defaults_changes[key] = value
            cli_overrides.remove(override)
        else:
            overrides.append(override)
    ConfigLoader._update_defaults(main_cfg, defaults_changes)
    cfg = main_cfg
    for default in main_cfg.defaults:
        if isinstance(default, DictConfig):
            is_optional = False
            if default.optional is not None:
                is_optional = default.optional
                del default['optional']
            family = next(iter(default.keys()))
            name = default[family]
            cfg = self._merge_config(cfg=cfg, cfg_dir=cfg_dir, is_pkg=is_pkg, family=family, name=name, required=not is_optional)
        else:
            assert isinstance(default, str)
            cfg = self._merge_config(cfg=cfg, cfg_dir=cfg_dir, is_pkg=is_pkg, family='.', name=default, required=True)
    cfg = OmegaConf.merge(cfg, OmegaConf.from_cli(overrides))
    del cfg['defaults']
    return cfg

def _create_cfg(self, cfg_dir, cfg_filename, cli_overrides=[], defaults_only=False):
    assert defaults_only == False
    is_pkg = cfg_dir.startswith('pkg://')
