def copr_add_build(username, coprname):
    form = forms.BuildForm()
    copr = coprs_logic.CoprsLogic.get(flask.g.user, username, coprname).first()
    if not copr:
        return page_not_found('Copr with name {0} does not exist.'.format(coprname))
    if form.validate_on_submit() and flask.g.user.can_build_in(copr):
        build = models.Build(pkgs=form.pkgs.data.replace('\n', ' '), copr=copr, chroots=copr.chroots, repos=copr.repos, user=flask.g.user, submitted_on=int(time.time()))
        if flask.g.user.proven:
            build.memory_reqs = form.memory_reqs.data
            build.timeout = form.timeout.data
        builds_logic.BuildsLogic.new(flask.g.user, build, copr, check_authorized=False)
        db.session.commit()
        flask.flash('Build was added')
        return flask.redirect(flask.url_for('coprs_ns.copr_detail', username=username, coprname=copr.name))
    else:
        return render_copr_detail_with_form(username, coprname, form)

def render_copr_detail_with_form(username, coprname, form):
    return coprs_general.copr_detail(username=username, coprname=coprname, build_form=form)

def set_tag_end_ms(tag, end_ms):
    with db_transaction():
        updated = Tag.update(lifetime_end_ms=end_ms).where(Tag.id == tag).where(Tag.lifetime_end_ms == tag.lifetime_end_ms).execute()
        if updated != 1:
            return (None, False)
        return (tag.lifetime_end_ms, True)

def _save_export_countries(self, interaction, validated_export_countries):
    existing_country_mapping = {export_country.country: export_country for export_country in interaction.export_countries.all()}
    new_country_mapping = {item['country']: item for item in validated_export_countries}
    for (new_country, export_data) in new_country_mapping.items():
        status = export_data['status']
        if new_country in existing_country_mapping:
            existing_country = existing_country_mapping[new_country]
            existing_country.status = status
            existing_country.save()
        else:
            InteractionExportCountry.objects.create(country=new_country, interaction=interaction, status=status, created_by=interaction.created_by)
        current_date = now()
        record_date = current_date if interaction.date > current_date else interaction.date
        interaction.company.add_export_country(new_country, status, record_date, interaction.created_by)

def _save_export_countries(self, interaction, validated_export_countries):
    existing_country_mapping = {export_country.country: export_country for export_country in interaction.export_countries.all()}
    new_country_mapping = {item['country']: item for item in validated_export_countries}
    for (new_country, export_data) in new_country_mapping.items():
        status = export_data['status']
        if new_country in existing_country_mapping:
            raise NotImplementedError('Updating export countries is not supported yet.')
        InteractionExportCountry.objects.create(country=new_country, interaction=interaction, status=status, created_by=interaction.created_by)
        current_date = now()
        record_date = current_date if interaction.date > current_date else interaction.date
        interaction.company.add_export_country(new_country, status, record_date, interaction.created_by)

def registeropt(self, name, valuetype, where, default):
    for opt in self.opts:
        if opt[0] == name:
            raise ValueError(f'Option name "{name}" is already registered.')
    self.opts.append((name, valuetype, where, default))

def announce(self, negotiated, nlris=None, mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size
    attr = self.attributes.pack(asn4, local_as, peer_as)
    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []
        for nlri in self.nlris:
            (afi, safi) = (nlri.afi, nlri.safi)
            addpath = negotiated.addpath.send(afi, safi)
            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and (nlri.nexthop == self.attributes.get(AID.NEXT_HOP, None)):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
    else:
        packed_nlri = nlris
        packed_mp = mps
    if not packed_nlri and (not packed_mp):
        return ''
    return self.make_message(msg_size, attr, MPRNLRI(packed_mp).pack(addpath), ''.join((nlri.pack(addpath) for nlri in packed_nlri)))

