def cache_comparison_jobs_and_inputs() -> tuple[Jobs, dict[str, Any]]:
    (cc_inputs, cc_env) = workflow_dispatch_inputs([WorkflowInput('PANTS_ARGS', 'string', default='check lint test ::'), WorkflowInput('BASE_REF', 'string', default='main'), WorkflowInput('BUILD_COMMIT', 'string'), WorkflowInput('SOURCE_DIFFSPEC', 'string'), WorkflowInput('SOURCE_DIFFSPEC_STEP', 'int', default=1)])
    helper = Helper(Platform.LINUX_X86_64)
    jobs = {'cache_comparison': {'runs-on': 'ubuntu-latest', 'timeout-minutes': 90, 'steps': [*checkout(), *helper.setup_primary_python(), *helper.expose_all_pythons(), {'name': 'Prepare cache comparison', 'run': dedent('
                        MODE=debug ./pants package build-support/bin/cache_comparison.py
                        git fetch --no-tags --depth=1024 origin "$BASE_REF"
                        '), 'env': cc_env}, {'name': 'Run cache comparison', 'run': dedent('
                        dist/build-support.bin/cache_comparison_py.pex                           --args="$PANTS_ARGS"                           --build-commit="$BUILD_COMMIT"                           --source-diffspec="$SOURCE_DIFFSPEC"                           --source-diffspec-step=$SOURCE_DIFFSPEC_STEP
                        '), 'env': cc_env}]}}
    return (jobs, cc_inputs)

def configure_net(self, net, pin_name, use):
    valid_uses = ['power', 'ground', 'signal']
    if use not in valid_uses:
        raise ValueError(f'Invalid use: {use}. Must be one of {valid_uses}.')
    if net in self.nets:
        self.nets[net]['use'] = use
        self.nets[net]['pin_name'] = pin_name
    else:
        self.nets[net] = {'use': use, 'pin_name': pin_name, 'wires': []}

def __eq__(self, other: object) -> bool:
    if not isinstance(other, Matrix):
        raise TypeError('Matrix class required.')
    if self.shape != other.shape:
        raise TypeError('Matrices have different shapes.')
    return np.allclose(self.matrix, other.matrix, atol=self.abs_tol)

def _get_data(self):
    try:
        data = self.connection.recv(4)
        if not data:
            time.sleep(1e-06)
            return self._get_data()
        length = int.from_bytes(data, 'little')
        chunks = []
        while len(chunks) < length:
            chunk = self.connection.recv(length - len(chunks))
            if not chunk:
                break
            chunks.append(chunk.decode())
        return ''.join(chunks)
    except socket.timeout as e:
        print('env timed out', e)
    return None

def gen(self, n: int, bounds: List[Tuple[float, float]], objective_weights: Tensor, outcome_constraints: Optional[Tuple[Tensor, Tensor]]=None, linear_constraints: Optional[Tuple[Tensor, Tensor]]=None, fixed_features: Optional[Dict[int, float]]=None, pending_observations: Optional[List[Tensor]]=None, model_gen_options: Optional[TConfig]=None, rounding_func: Optional[Callable[[Tensor], Tensor]]=None, target_fidelities: Optional[Dict[int, float]]=None) -> Tuple[Tensor, Tensor, TGenMetadata, List[Optional[TCandidateMetadata]]]:
    for b in bounds:
        assert b == (-1, 1)
    assert linear_constraints is None
    assert fixed_features is None
    assert pending_observations is None
    A = torch.cat((self.Binv, -self.Binv))
    b = torch.ones(2 * self.Binv.shape[0], 1, dtype=self.dtype, device=self.device)
    linear_constraints = (A, b)
    noiseless = max((Yvar.min().item() for Yvar in self.Yvars)) < 1e-05
    if model_gen_options is None:
        model_gen_options = {}
    model_gen_options = {'acquisition_function_kwargs': {'q': n, 'noiseless': noiseless}, 'optimizer_kwargs': {'raw_samples': model_gen_options.get('raw_samples', 1000), 'num_restarts': model_gen_options.get('num_restarts', 10), 'B': self.B}}
    (Xd_opt, w, gen_metadata, _) = super().gen(n=n, bounds=[(-100000000.0, 100000000.0)] * self.B.shape[0], objective_weights=objective_weights, outcome_constraints=outcome_constraints, linear_constraints=linear_constraints, model_gen_options=model_gen_options)
    Xopt = (self.Binv @ Xd_opt.t()).t()
    if Xopt.min() < -1 or Xopt.max() > 1:
        logger.debug(f'Clipping from [{Xopt.min()}, {Xopt.max()}]')
        Xopt = torch.clamp(Xopt, min=-1.0, max=1.0)
    return (Xopt, w, gen_metadata, [])

def get(self, sess_id):
    user = self.request.remote_user or '@public'
    session = self.app.db.sessions.find_one({'_id': bson.objectid.ObjectId(sess_id)})
    if not session:
        self.abort(404)
    experiment = self.app.db.experiments.find_one({'_id': bson.objectid.ObjectId(session['experiment'])})
    if not experiment:
        self.abort(500)
    if user not in experiment['permissions']:
        self.abort(403)
    query = {'session': bson.objectid.ObjectId(sess_id)}
    projection = ['timestamp', 'series', 'acquisition', 'description', 'datatype']
    epochs = list(self.app.db.epochs.find(query, projection))
    self.response.write(json.dumps(epochs, default=bson.json_util.default))

def infer_type(self, expr: E.Apply) -> T.Base:
    if len(expr.arguments) != 1:
        raise Error.WrongArity(expr, 1)
    if not isinstance(expr.arguments[0].type, T.Array) or (expr.arguments[0]._check_quant and expr.arguments[0].type.optional):
        raise Error.StaticTypeMismatch(expr.arguments[0], T.Array(T.Any()), expr.arguments[0].type)
    if expr.arguments[0].type.item_type is None:
        raise Error.IndeterminateType(expr.arguments[0])
    if isinstance(expr.arguments[0].type.item_type, T.Any):
        raise Error.EmptyArray(expr.arguments[0])
    ty = expr.arguments[0].type.item_type
    assert isinstance(ty, T.Base)
    return ty.copy(optional=False)

