    return {'rname': lambda x, m=tIdMap: m[x.tId], 'length': lambda x: x.aEnd - x.aStart, 'qname': lambda x: x.qId, 'zm': lambda x: x.holeNumber, 'pos': lambda x: x.tStart, 'readstart': lambda x: x.aStart, 'tstart': lambda x: x.tStart if overlaps(x.tStart, x.tEnd, x.aStart, x.aEnd) else None, 'tend': lambda x: x.tEnd if overlaps(x.tStart, x.tEnd, x.aStart, x.aEnd) else None}

