def _preprocess(self, dataset, fit=False):
    blocks_by_depth = self._dynamically_group_blocks_by_depth()
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

def _dynamically_group_blocks_by_depth(self):
    blocks_by_depth = []
    depth_count = 0
    while True:
        temp_blocks = []
        for block in self._blocks:
            if self._should_process_block(block, depth_count):
                temp_blocks.append(block)
        if not temp_blocks:
            break
        blocks_by_depth.append(temp_blocks)
        depth_count += 1
    return blocks_by_depth

def _should_process_block(self, block, depth):
    return True

def _preprocess(self, dataset, fit=False):
    blocks_by_depth = []
    remaining_blocks = self._blocks[:]
    while remaining_blocks:
        temp_blocks = []
        for block in remaining_blocks:
            if isinstance(block, preprocessor.Preprocessor):
                block_depth = self._block_topo_depth[self._block_to_id[block]]
                if block_depth == len(blocks_by_depth):
                    temp_blocks.append(block)
        if not temp_blocks:
            break
        blocks_by_depth.append(temp_blocks)
        remaining_blocks = [b for b in remaining_blocks if b not in temp_blocks]
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

