def requeue(self, queue=None):
    if not queue:
        if not self.data or not self.data.get('queue'):
            self.fetch(full_data=False)
        queue = self.data['queue']
    self.save_status('queued', queue=queue)
    Queue(queue).enqueue_job_ids([str(self.id)])

def setUp(self):
    super().setUp()
    self._testkit_test_name = id_ = re.sub('^([^\\.]+\\.)*?tests\\.', '', self.id())
    self._check_subtests = False
    self._backend = new_backend()
    self.addCleanup(self._backend.close)
    self._driver_features = get_driver_features(self._backend)
    if self.required_features:
        self.skip_if_missing_driver_features(*self.required_features)
    response = self._backend.send_and_receive(protocol.StartTest(id_))
    if isinstance(response, protocol.SkipTest):
        self.skipTest(response.reason)
    response = self._backend.send_and_receive(protocol.StartTest(id_))
    if isinstance(response, protocol.SkipTest):
        self.skipTest(response.reason)
    elif isinstance(response, protocol.RunSubTests):
        self._check_subtests = True
    elif not isinstance(response, protocol.RunTest):
        raise Exception('Should be SkipTest, RunSubTests, or RunTest, received {}: {}'.format(type(response), response))

def map_objects_by_bounding_box(request):
    data = request.POST
    album_id = data.get('album_id') or None
    area_id = data.get('area_id') or None
    limit_by_album = data.get('limit_by_album') in ['true', True]
    qs = Photo.objects.all()
    ungeotagged_count = 0
    geotagged_count = 0
    if album_id is not None or area_id is not None:
        (ungeotagged_count, geotagged_count) = qs.get_album_photo_count_and_total_geotag_count(album_id, area_id)
        if album_id and limit_by_album:
            album = Album.objects.get(pk=album_id)
            album_photo_ids = list(album.photos.values_list('id', flat=True))
            for sa in album.subalbums.all():
                album_photo_ids += list(sa.photos.values_list('id', flat=True))
            qs = qs.filter(id__in=album_photo_ids)
    if data.get('sw_lat') and data.get('sw_lon') and data.get('ne_lat') and data.get('ne_lon'):
        bounding_box = (float(data.get('sw_lat')), float(data.get('sw_lon')), float(data.get('ne_lat')), float(data.get('ne_lon')))
        data = qs.get_geotagged_photos_list(bounding_box)
        data = {'photos': data, 'geotagged_count': geotagged_count, 'ungeotagged_count': ungeotagged_count}
    else:
        data = {'photos': [], 'geotagged_count': 0, 'ungeotagged_count': 0}
    return HttpResponse(json.dumps(data), content_type='application/json')

def serialize_product(product):
    json = {'plScore': None, 'verified': False, 'report': 'ask_for_company', 'id': product.id, 'code': product.code}
    company = product.company
    if company:
        json['report'] = False
        json['company'] = {}
        json['company']['name'] = company.common_name or company.official_name or company.name
        json['company']['plCapital'] = company.plCapital
        json['company']['plCapital_notes'] = company.plCapital_notes
        json['company']['plWorkers'] = company.plWorkers
        json['company']['plWorkers_notes'] = company.plWorkers_notes
        json['company']['plRnD'] = company.plRnD
        json['company']['plRnD_notes'] = company.plRnD_notes
        json['company']['plRegistered'] = company.plRegistered
        json['company']['plRegistered_notes'] = company.plRegistered_notes
        json['company']['plNotGlobEnt'] = company.plNotGlobEnt
        json['company']['plNotGlobEnt_notes'] = company.plNotGlobEnt_notes
        plScore = get_plScore(company)
        if plScore:
            json['plScore'] = plScore
            json['verified'] = company.verified
    else:
        for prefix in CODE_PREFIX_TO_COUNTRY.keys():
            if product.code.startswith(prefix):
                json['plScore'] = 0
                json['verified'] = False
                json['company'] = {}
                json['company']['name'] = 'Miejsce produkcji: {}'.format(CODE_PREFIX_TO_COUNTRY[prefix])
    return json

def url_join(base, url, allow_fragments=True):
    if isinstance(base, tuple):
        base = url_unparse(base)
    if isinstance(url, tuple):
        url = url_unparse(url)
    base, url = normalize_string_tuple((base, url))
    s = make_literal_wrapper(base)
    if not base:
        return url
    if not url:
        return base
    bscheme, bnetloc, bpath, bquery, bfragment =
        url_parse(base, allow_fragments=allow_fragments)
    scheme, netloc, path, query, fragment =
        url_parse(url, bscheme, allow_fragments)
    if scheme != bscheme:
        return url
    if netloc:
        return url_unparse((scheme, netloc, path, query, fragment))
    netloc = bnetloc
    if path[:1] == s('/'):
        return url_unparse((scheme, netloc, path, query, fragment))
    if not path:
        path = bpath
        if not query:
            query = bquery
        return url_unparse((scheme, netloc, path, query, fragment))
    segments = bpath.split(s('/'))[:-1] + path.split(s('/'))
    segments = [segment for segment in segments if segment not in (s(''), s('.'))]
    stack = []
    for segment in segments:
        if segment == s('..'):
            if stack:
                stack.pop()
        else:
            stack.append(segment)
    final_path = s('/').join(stack)
    return url_unparse((scheme, netloc, final_path, query, fragment))

