def __get_k8s_containers(self, job_wrapper):
    k8s_container = {'name': self.__get_k8s_container_name(job_wrapper), 'image': self._find_container(job_wrapper).container_id, 'command': [job_wrapper.shell, '-c', job_wrapper.runner_command_line], 'workingDir': job_wrapper.working_directory, 'volumeMounts': [{'mountPath': self.runner_params['k8s_persistent_volume_claim_mount_path'], 'name': self._galaxy_vol_name}]}
    resources = self.__get_resources(job_wrapper)
    if resources:
        k8s_container['resources'] = resources
    if self._default_pull_policy:
        k8s_container['imagePullPolicy'] = self._default_pull_policy
    return [k8s_container]

def _stream_logs_to_output(self) -> None:
    if not self.cli:
        raise Exception("The 'cli' should be initialized before!")
    if not self.service:
        raise Exception("The 'service' should be initialized before!")
    logs = self.cli.service_logs(self.service['ID'], follow=True, stdout=True, stderr=True, is_tty=self.tty)
    line = ''
    while True:
        try:
            log = next(logs)
        except StopIteration:
            break
        else:
            try:
                log = log.decode()
            except UnicodeDecodeError:
                continue
            if log == '\n':
                self.log.info(line)
                line = ''
            else:
                line += log
    if line:
        self.log.info(line)

def _concatenate_components(reps_difs, names):
    values = []
    for name in names:
        data_vals = []
        for x in reps_difs:
            data_val = getattr(x, name)
            data_vals.append(data_val.reshape(1) if x.isscalar else data_val)
        concat_vals = np.concatenate(data_vals)
        if isinstance(concat_vals, u.Quantity):
            concat_vals = concat_vals.to(data_val.unit)
        values.append(concat_vals)
    return values

def get(method, hmc, uri, uri_parms, logon_required):
    cpc_oid = uri_parms[0]
    query_str = uri_parms[1]
    try:
        cpc = hmc.cpcs.lookup_by_oid(cpc_oid)
    except KeyError:
        new_exc = InvalidResourceError(method, uri)
        new_exc.__cause__ = None
        raise new_exc
    if cpc.dpm_enabled:
        raise HTTPError(method, uri, 400, 149, 'CPC is DPM enabled, cannot list image activation profiles.')
    result_profiles = []
    filter_args = parse_query_parms(method, uri, query_str)
    for profile in cpc.image_activation_profiles.list(filter_args):
        result_profile = {}
        for prop in profile.properties:
            if prop in ('element-uri', 'name'):
                result_profile[prop] = profile.properties[prop]
        result_profiles.append(result_profile)
    if not result_profiles:
        return {'image-activation-profiles': []}
    return {'image-activation-profiles': result_profiles}

def getMemberNames(self):
    assert self.isCollection
    childset = set()
    l = len(self.path)
    for f in self.provider.files:
        if f.startswith(self.path):
            p = f[l:]
            if '/' in p:
                p = p.split('/')[0]
            childset.add(p)
        elif childset:
            break
    return list(childset)

def getMemberNames(self):
    assert self.isCollection
    childlist = []
    l = len(self.path)
    last_appended = None
    for f in self.provider.files:
        if f.startswith(self.path):
            p = f[l:]
            if '/' in p:
                p = p.split('/')[0]
            if p != last_appended:
                childlist.append(p)
                last_appended = p
        elif childlist:
            break
    return childlist

def mark(testcase, security, severity):
    testcase.security_flag = security
    if security:
        bisection.notify_bisection_security(testcase)
        if not severity:
            severity = severity_analyzer.get_security_severity(testcase.crash_type, testcase.crash_stacktrace, testcase.job_type, bool(testcase.gestures))
        testcase.security_severity = severity
    else:
        bisection.notify_bisection_invalid(testcase)
    testcase.put()
    helpers.log(f'Set security flags on testcase {testcase.key.id()} to {security}.', helpers.MODIFY_OPERATION)

