def __call__(self, acquire):
    if isinstance(acquire, IOResult):
        return acquire.bind(self._ioresult_pipeline)
    elif isinstance(acquire, RequiresContextIOResult):
        return acquire.bind(self._reader_ioresult_pipeline)
    elif isinstance(acquire, RequiresContextFutureResult):
        return acquire.bind(self._future_pipeline)
    return acquire.bind_async(self._future_pipeline)

import jwt

def _perform_login(self, request: HttpRequest) -> HttpResponse:
    code = request.GET.get('code')
    user_data = self._fetch_user_data(code)
    if user_data is None:
        log.warning('Unable to log in due to problem on Sentry', exc_info=True)
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/login')
    id_token = request.GET.get('id_token')
    try:
        decoded_token = jwt.decode(id_token, settings.JWT_SHARED_SECRET, algorithms=['HS256'])
    except jwt.ExpiredSignatureError:
        log.warning('ID token has expired')
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/login')
    except jwt.InvalidTokenError:
        log.warning('Invalid ID token')
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/login')
    current_user = self._login_user(request, user_data)
    owner = current_user.owners.first()
    if owner is not None:
        service = get_short_service_name(owner.service)
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/{service}')
    else:
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/sync')

def _addExtraCfg(self, cmd, devices=tuple(), use_lvmpolld=True):
    newcmd = [constants.EXT_LVM, cmd[0]]
    if devices:
        dev_filter = _buildFilter(devices)
    else:
        dev_filter = self._getCachedFilter()
    conf = _buildConfig(dev_filter=dev_filter, use_lvmpolld='1' if use_lvmpolld else '0')
    newcmd += ['--config', conf]
    if len(cmd) > 1:
        newcmd += cmd[1:]
    return newcmd

def add_flair(paragraphs: List[str], gens: Dict[str, Any]) -> List[str]:
    results = []
    flair = get_flair_gen(len(paragraphs))
    for i in range(len(paragraphs)):
        key = flair[i]
        if key == 'None':
            txt = paragraphs[i]
        elif key == 'italic':
            txt = add_md('*', paragraphs[i])
        elif key == 'bold':
            txt = add_md('**', paragraphs[i])
        elif key == 'strike-thru':
            txt = add_md('~~', paragraphs[i])
        elif key == 'quoted':
            txt = '>' + paragraphs[i]
        elif key == 'quote-block':
            txt = paragraphs[i] + '\n' + next(gens['quote-blocks'])
        elif key == 'inline-code':
            txt = paragraphs[i] + '\n' + next(gens['inline-code'])
        elif key == 'code-block':
            txt = paragraphs[i] + '\n' + next(gens['code-blocks'])
        elif key == 'math':
            txt = paragraphs[i] + '\n' + next(gens['maths'])
        elif key == 'list':
            txt = paragraphs[i] + '\n' + next(gens['lists'])
        elif key == 'emoji':
            txt = add_emoji(paragraphs[i], next(gens['emojis']))
        elif key == 'link':
            txt = add_link(paragraphs[i], next(gens['links']))
        elif key == 'picture':
            txt = paragraphs[i] + '\n' + next(gens['pictures'])
        results.append(txt)
    return results

