class ClassFrequencyMachine:

    def __init__(self):
        self.coeff_dict = {}

    def set_coefficients(self, component, coeffs):
        self.coeff_dict[component] = coeffs

    def EvalPolyApparent(self, component):
        coeffs = self.coeff_dict.get(component)
        if coeffs is None:
            raise ValueError(f"Coefficients for component '{component}' not found.")
        return self.SAX.dot(coeffs)

