    if not self.pci_requests:
        self.pci_requests = objects.InstancePCIRequests.get_by_instance_uuid(self._context, self.uuid)

def group_execute_trigger(self, *resources: GPIBInstrument) -> Tuple[int, constants.StatusCode]:
    if not resources:
        raise ValueError('No resources provided.')
    for resource in resources:
        if not isinstance(resource, GPIBInstrument):
            raise ValueError('%r is not a GPIBInstrument' % resource)
    board_id = resources[0].board_id
    for resource in resources:
        if resource.board_id != board_id:
            raise ValueError('All resources must be on the same board.')
    if not self.is_controller_in_charge:
        self.send_ifc()
    command = [64, 32 + 31]
    for resource in resources:
        command.append(32 + resource.primary_address)
    command.append(8)
    return self.send_command(bytes(command))

def _get_loss(self, sample_weight):
    if self.loss != 'log_loss':
        warnings.warn(f"The loss '{self.loss}' was deprecated in v1.1 and will be removed in version 1.3. Use 'log_loss' which is equivalent.", FutureWarning)
    if self.n_trees_per_iteration_ == 1:
        return HalfBinomialLoss(sample_weight=sample_weight)
    else:
        return HalfMultinomialLoss(sample_weight=sample_weight, n_classes=self.n_trees_per_iteration_)

def main(request):
    is_locked = check_app_locked()
    if is_locked and (not has_role(request.user, 'Secretariat')):
        message = get_lock_message()
        return render(request, 'sreq/locked.html', {'message': message})
    meeting = get_meeting()
    (scheduled_groups, unscheduled_groups) = groups_by_session(request.user, meeting, types=['wg', 'rg', 'ag'])
    if not scheduled_groups and (not unscheduled_groups):
        messages.warning(request, 'The account %s is not associated with any groups.  If you have multiple Datatracker accounts you may try another or report a problem to ietf-action@ietf.org' % request.user)
    choices = zip([g.pk for g in unscheduled_groups], [str(g) for g in unscheduled_groups])
    form = GroupSelectForm(choices=choices)
    for group in scheduled_groups:
        sessions = group.session_set.filter(meeting=meeting)
        if sessions.count() < 3:
            group.status_message = sessions[0].status
        else:
            group.status_message = 'First two sessions: %s, Third session: %s' % (sessions[0].status, sessions[2].status)
    for group in unscheduled_groups:
        if group.session_set.filter(meeting=meeting, status='notmeet'):
            group.not_meeting = True
    return render(request, 'sreq/main.html', {'is_locked': is_locked, 'form': form, 'meeting': meeting, 'scheduled_groups': scheduled_groups, 'unscheduled_groups': unscheduled_groups})

def unmarshal_Int64(space, u, tc):
    if LONG_BIT >= 64:
        lo = u.get_int() & 2 ** 32 - 1
        hi = u.get_int()
        return space.newint(hi << 32 | lo)
    else:
        byte_array = bytearray()
        byte_array.append(u.get_short() & 65535)
        byte_array.append(u.get_short() & 65535)
        byte_array.extend(u.get_int().to_bytes(4, byteorder='little'))
        return _PyLong_FromByteArray(byte_array, len(byte_array), 1, 0)

def delete_workspace(self, workspace_id: str):
    logging.info(f"deleting workspace '{workspace_id}'")
    if self.workspace_exists(workspace_id):
        workspace = self.orchestrator_state.get_workspace(workspace_id)
        try:
            for category_id in workspace.categories.keys():
                self._delete_category_models(workspace_id, category_id)
                self.data_access.delete_labels_for_category(workspace_id, category_id, workspace.dataset_name)
            self.orchestrator_state.delete_workspace_state(workspace_id)
        except Exception as e:
            logging.exception(f"error deleting workspace '{workspace_id}'")
            raise e
        try:
            self.data_access.delete_all_labels(workspace_id, workspace.dataset_name)
        except Exception as e:
            logging.exception(f"error clearing saved labels for workspace '{workspace_id}'")
            raise e

