def _covering_set_of_owners_for(self, files):
    every_owner = set()
    owner_count = {}
    for f in files:
        dirname = self.os_path.dirname(f)
        while dirname in self.owners_for:
            for owner in self.owners_for[dirname]:
                if owner not in owner_count:
                    owner_count[owner] = 0
                owner_count[owner] += 1
            if self._stop_looking(dirname):
                break
            dirname = self.os_path.dirname(dirname)
    sorted_owners = sorted(owner_count.items(), key=lambda item: item[1], reverse=True)
    selected_owners = set()
    covered_files = set()
    for (owner, count) in sorted_owners:
        selected_owners.add(owner)
        for f in files:
            dirname = self.os_path.dirname(f)
            while dirname in self.owners_for:
                if owner in self.owners_for[dirname]:
                    covered_files.add(f)
                if len(covered_files) == len(files):
                    break
                dirname = self.os_path.dirname(dirname)
        if len(covered_files) == len(files):
            break
    return selected_owners

def _covering_set_of_owners_for(self, files):
    every_owner = set()
    owner_combinations = []
    for f in files:
        dirname = self.os_path.dirname(f)
        current_owners = set()
        while dirname in self.owners_for:
            current_owners |= self.owners_for[dirname]
            if self._stop_looking(dirname):
                break
            dirname = self.os_path.dirname(dirname)
        if current_owners:
            owner_combinations.append(current_owners)
    if owner_combinations:
        min_length = min((len(owners) for owners in owner_combinations))
        every_owner = {owner for owners in owner_combinations if len(owners) == min_length for owner in owners}
    return every_owner

